# --- METRICS ---
# line_count: 9
# cyclomatic_complexity: 3
# max_nesting_depth: 2

# --- FUNCTION: cache_read_memshare ---
sub cache_read_memshare {
  my($self, $filename) = @_;

  return unless($MemShareCache{$filename});
  return unless($MemShareCache{$filename}->[0] > (stat($filename))[9]);

  return($MemShareCache{$filename}->[1]);

}

