package XML::Simple;

# --- INCLUDES ---
use strict;
use warnings;
use warnings::register;
use Carp;
use Scalar::Util qw();
require Exporter;
use vars qw($VERSION @ISA @EXPORT @EXPORT_OK $PREFERRED_PARSER);
require File::Basename;
require XML::SAX;
require XML::Parser;
require Storable;
require Storable;
require Storable;
require XML::NamespaceSupport;
require IO::Handle;
require XML::SAX;
require File::Basename;
require File::Spec;

# --- METRICS ---
# line_count: 9
# cyclomatic_complexity: 3
# max_nesting_depth: 2

# --- HINTS ---
# external_call: Storable::dclone
# --- FUNCTION: cache_read_memcopy ---
sub cache_read_memcopy {
  my($self, $filename) = @_;

  return unless($MemCopyCache{$filename});
  return unless($MemCopyCache{$filename}->[0] > (stat($filename))[9]);

  return(Storable::dclone($MemCopyCache{$filename}->[1]));

}

