# --- METRICS ---
# line_count: 14
# cyclomatic_complexity: 2
# max_nesting_depth: 3

# --- HINTS ---
# method_chain: need: $self->{opt}
# method_chain: need: $self->numeric_escape
# --- FUNCTION: escape_value ---
sub escape_value {
  my($self, $data) = @_;

  return '' unless(defined($data));

  $data =~ s/&/&amp;/sg;
  $data =~ s/</&lt;/sg;
  $data =~ s/>/&gt;/sg;
  $data =~ s/"/&quot;/sg;

  my $level = $self->{opt}->{numericescape} or return $data;

  return $self->numeric_escape($data, $level);
}

