# --- METRICS ---
# line_count: 8
# cyclomatic_complexity: 2
# max_nesting_depth: 3

# --- HINTS ---
# method_chain: need: $self->handle_options
# method_chain: need: $self->{opt}
# method_chain: need: $self->{lists}
# method_chain: need: $self->{curlist}
# method_chain: need: $self->{tree}
# --- FUNCTION: start_document ---
sub start_document {
  my $self = shift;

  $self->handle_options('in') unless($self->{opt});

  $self->{lists} = [];
  $self->{curlist} = $self->{tree} = [];
}

