# --- METRICS ---
# line_count: 15
# cyclomatic_complexity: 2
# max_nesting_depth: 2

# --- HINTS ---
# if/else: branches
# method_chain: need: $chars->{Data}
# method_chain: need: $self->{curlist}
# method_chain: need: $clist->[$pos - 1]
# method_chain: need: $clist->[$pos]
# --- FUNCTION: characters ---
sub characters {
  my $self  = shift;
  my $chars = shift;

  my $text  = $chars->{Data};
  my $clist = $self->{curlist};
  my $pos = $#$clist;

  if ($pos > 0 and $clist->[$pos - 1] eq '0') {
    $clist->[$pos] .= $text;
  }
  else {
    push @$clist, 0 => $text;
  }
}

